/* ============================================================
   Design tokens
   ============================================================ */
:root {
  --color-bg:         #0b0b10;
  --color-surface:    #13131e;
  --color-surface-2:  #1b1b2a;
  --color-surface-3:  #22223a;
  --color-text:       #eeeef5;
  --color-muted:      #8888a2;
  --color-subtle:     #55556a;
  --color-accent:     #d4a853;
  --color-accent-alt: #e8be6e;
  --color-deal:       #e05c5c;
  --color-deal-bg:    #2a1010;
  --color-border:     #2a2a40;
  --color-focus:      #6b9cff;
  --color-link:       #a8c4ff;
  --radius-sm:        6px;
  --radius-md:        12px;
  --radius-lg:        18px;
  --shadow-card:      0 2px 16px rgba(0,0,0,.55);
  --shadow-hover:     0 8px 32px rgba(0,0,0,.7);
  --transition:       0.2s ease;
  --font-sans:        'Segoe UI', system-ui, -apple-system, sans-serif;
}

/* ============================================================
   Reset & base
   ============================================================ */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; }

body {
  background-color: var(--color-bg);
  color: var(--color-text);
  font-family: var(--font-sans);
  font-size: 1rem;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

img { display: block; max-width: 100%; height: auto; }
a { color: var(--color-link); text-decoration: underline; }
a:hover { color: var(--color-accent-alt); }
ul, ol { list-style: none; }

/* ============================================================
   Skip link
   ============================================================ */
.skip-link {
  position: absolute;
  top: 0;
  left: 0;
  padding: 0.75rem 1.25rem;
  background: var(--color-accent);
  color: #000;
  font-weight: 700;
  border-radius: 0 0 var(--radius-sm) 0;
  z-index: 1000;
  text-decoration: none;
}
.skip-link:not(:focus):not(:active) {
  clip: rect(0 0 0 0);
  clip-path: inset(50%);
  height: 1px;
  overflow: hidden;
  position: absolute;
  white-space: nowrap;
  width: 1px;
}
.skip-link:focus { outline: 3px solid #000; outline-offset: 2px; }

/* ============================================================
   Focus styles (global)
   ============================================================ */
:focus-visible {
  outline: 3px solid var(--color-focus);
  outline-offset: 3px;
}
/* paired transparent outline for forced-colors */
:focus-visible {
  box-shadow: 0 0 0 3px var(--color-focus);
  outline: 2px solid transparent;
}

/* ============================================================
   Screen-reader only utility
   ============================================================ */
.sr-only {
  clip: rect(0 0 0 0);
  clip-path: inset(50%);
  height: 1px;
  overflow: hidden;
  position: absolute;
  white-space: nowrap;
  width: 1px;
}

/* ============================================================
   Layout utilities
   ============================================================ */
.container {
  width: min(100%, 1280px);
  margin-inline: auto;
  padding-inline: 1.5rem;
}

section { padding-block: 5rem; }

.section-header {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 1rem;
  flex-wrap: wrap;
  margin-bottom: 2.5rem;
}
.section-title {
  font-size: clamp(1.5rem, 3vw, 2rem);
  font-weight: 700;
  letter-spacing: -0.02em;
  color: var(--color-text);
}
.section-link {
  font-size: 0.9rem;
  font-weight: 600;
  color: var(--color-accent);
  text-decoration: none;
  white-space: nowrap;
}
.section-link:hover { color: var(--color-accent-alt); text-decoration: underline; }

/* ============================================================
   Buttons
   ============================================================ */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.7rem 1.5rem;
  border-radius: var(--radius-sm);
  font-family: inherit;
  font-size: 0.95rem;
  font-weight: 600;
  cursor: pointer;
  text-decoration: none;
  transition: background var(--transition), color var(--transition), transform var(--transition);
  border: 2px solid transparent;
}
.btn:focus-visible {
  outline: 2px solid transparent;
  box-shadow: 0 0 0 3px var(--color-focus);
}
.btn-primary {
  background: var(--color-accent);
  color: #0b0b10;
}
.btn-primary:hover {
  background: var(--color-accent-alt);
  color: #0b0b10;
  transform: translateY(-1px);
}
.btn-outline {
  background: transparent;
  color: var(--color-accent);
  border-color: var(--color-accent);
}
.btn-outline:hover {
  background: var(--color-accent);
  color: #0b0b10;
}
.btn-ghost {
  background: var(--color-surface-2);
  color: var(--color-text);
  border-color: var(--color-border);
}
.btn-ghost:hover { background: var(--color-surface-3); }

.btn-icon {
  background: none;
  border: none;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.5rem;
  border-radius: var(--radius-sm);
  color: var(--color-text);
  transition: background var(--transition);
}
.btn-icon:hover { background: var(--color-surface-2); }
.btn-icon:focus-visible {
  outline: 2px solid transparent;
  box-shadow: 0 0 0 3px var(--color-focus);
}

/* ============================================================
   Divider
   ============================================================ */
.divider {
  border: none;
  border-top: 1px solid var(--color-border);
}

/* ============================================================
   HEADER
   ============================================================ */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(11, 11, 16, 0.9);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--color-border);
}
.header-inner {
  display: flex;
  align-items: center;
  gap: 2rem;
  height: 4rem;
}
.site-logo {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  text-decoration: none;
  flex-shrink: 0;
}
.logo-mark {
  width: 36px;
  height: 36px;
  background: var(--color-accent);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.1rem;
}
.logo-text {
  font-size: 1.2rem;
  font-weight: 800;
  letter-spacing: -0.03em;
  color: var(--color-text);
}
.logo-text span { color: var(--color-accent); }

/* Primary nav */
.primary-nav { margin-inline-start: auto; }
.nav-list {
  display: flex;
  gap: 0.25rem;
}
.nav-link {
  display: inline-block;
  padding: 0.5rem 0.75rem;
  border-radius: var(--radius-sm);
  font-size: 0.9rem;
  font-weight: 500;
  color: var(--color-muted);
  text-decoration: none;
  transition: color var(--transition), background var(--transition);
}
.nav-link:hover,
.nav-link[aria-current="page"] {
  color: var(--color-text);
  background: var(--color-surface-2);
}
.nav-link[aria-current="page"] { color: var(--color-accent); }

/* Header actions */
.header-actions {
  display: flex;
  align-items: center;
  gap: 0.25rem;
  margin-inline-start: auto;
}
.cart-count {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 1.25rem;
  height: 1.25rem;
  padding: 0 0.25rem;
  background: var(--color-accent);
  color: #0b0b10;
  font-size: 0.7rem;
  font-weight: 700;
  border-radius: 999px;
  margin-inline-start: -0.5rem;
  margin-block-end: 1rem;
}

/* Mobile menu toggle */
.menu-toggle { display: none; }

/* ============================================================
   HERO
   ============================================================ */
.hero {
  position: relative;
  min-height: min(90vh, 680px);
  display: flex;
  align-items: center;
  overflow: hidden;
  padding-block: 4rem;
}
.hero-bg {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse 70% 60% at 70% 50%, rgba(212,168,83,.12) 0%, transparent 70%),
    radial-gradient(ellipse 50% 80% at 20% 80%, rgba(107,156,255,.08) 0%, transparent 60%),
    linear-gradient(135deg, #0e0e18 0%, #0b0b10 60%, #100e18 100%);
  z-index: 0;
}
/* Decorative grid */
.hero-bg::after {
  content: '';
  position: absolute;
  inset: 0;
  background-image:
    linear-gradient(var(--color-border) 1px, transparent 1px),
    linear-gradient(90deg, var(--color-border) 1px, transparent 1px);
  background-size: 60px 60px;
  opacity: 0.3;
  mask-image: radial-gradient(ellipse 80% 60% at 50% 50%, #000 40%, transparent 100%);
}
.hero-content {
  position: relative;
  z-index: 1;
  max-width: 680px;
}
.hero-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  font-size: 0.8rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--color-accent);
  margin-bottom: 1.25rem;
  background: rgba(212,168,83,.1);
  padding: 0.35rem 0.75rem;
  border-radius: 999px;
  border: 1px solid rgba(212,168,83,.25);
}
.hero-title {
  font-size: clamp(2.5rem, 6vw, 4.5rem);
  font-weight: 800;
  line-height: 1.1;
  letter-spacing: -0.03em;
  margin-bottom: 1.5rem;
}
.hero-title em {
  font-style: normal;
  color: var(--color-accent);
}
.hero-subtitle {
  font-size: clamp(1rem, 2vw, 1.2rem);
  color: var(--color-muted);
  max-width: 500px;
  margin-bottom: 2.5rem;
  line-height: 1.7;
}
.hero-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 1rem;
  align-items: center;
}
.hero-stats {
  display: flex;
  gap: 2.5rem;
  margin-top: 3.5rem;
  padding-top: 2rem;
  border-top: 1px solid var(--color-border);
}
.stat-number {
  font-size: 1.75rem;
  font-weight: 800;
  color: var(--color-accent);
  letter-spacing: -0.03em;
}
.stat-label { font-size: 0.8rem; color: var(--color-muted); margin-top: 0.1rem; }

/* ============================================================
   ANNOUNCEMENT BANNER
   ============================================================ */
.announcement-bar {
  background: var(--color-accent);
  color: #0b0b10;
  text-align: center;
  padding: 0.5rem 1rem;
  font-size: 0.85rem;
  font-weight: 600;
}
.announcement-bar a {
  color: inherit;
  font-weight: 700;
  margin-inline-start: 0.5rem;
}

/* ============================================================
   FEATURED PRODUCTS
   ============================================================ */
.featured-products { background: var(--color-surface); }

.product-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
  gap: 1.5rem;
}

.product-card {
  background: var(--color-surface-2);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  box-shadow: var(--shadow-card);
  transition: transform var(--transition), box-shadow var(--transition);
  position: relative;
}
.product-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-hover);
}

.product-image-wrap {
  position: relative;
  aspect-ratio: 4/3;
  overflow: hidden;
}
.product-image {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.4s ease;
}
.product-card:hover .product-image { transform: scale(1.05); }

.product-badge {
  position: absolute;
  top: 0.75rem;
  left: 0.75rem;
  padding: 0.25rem 0.6rem;
  border-radius: 999px;
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}
.badge-new { background: var(--color-accent); color: #000; }
.badge-sale { background: var(--color-deal); color: #fff; }
.badge-hot { background: #9b59b6; color: #fff; }

.product-wishlist {
  position: absolute;
  top: 0.75rem;
  right: 0.75rem;
  background: rgba(19,19,30,.8);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-sm);
  width: 2rem;
  height: 2rem;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: background var(--transition);
  color: var(--color-muted);
}
.product-wishlist:hover { background: var(--color-surface-3); color: var(--color-deal); }
.product-wishlist:focus-visible {
  outline: 2px solid transparent;
  box-shadow: 0 0 0 3px var(--color-focus);
}
.product-wishlist[aria-pressed="true"] { color: var(--color-deal); }

.product-body {
  padding: 1.25rem;
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}
.product-category {
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--color-muted);
}
.product-name {
  font-size: 1rem;
  font-weight: 600;
  color: var(--color-text);
  line-height: 1.4;
}
.product-rating {
  display: flex;
  align-items: center;
  gap: 0.4rem;
}
.stars { color: var(--color-accent); font-size: 0.8rem; line-height: 1; }
.rating-count { font-size: 0.78rem; color: var(--color-muted); }

.product-price-row {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  flex-wrap: wrap;
  margin-top: auto;
}
.price-current {
  font-size: 1.2rem;
  font-weight: 700;
  color: var(--color-accent);
}
.price-original {
  font-size: 0.9rem;
  color: var(--color-muted);
  text-decoration: line-through;
}
.price-save {
  font-size: 0.75rem;
  font-weight: 700;
  color: var(--color-deal);
  background: var(--color-deal-bg);
  padding: 0.15rem 0.45rem;
  border-radius: 999px;
}

.product-footer {
  padding: 1rem 1.25rem;
  border-top: 1px solid var(--color-border);
}
.add-to-cart {
  width: 100%;
  justify-content: center;
}

/* ============================================================
   DEALS SECTION
   ============================================================ */
.deals-section { background: var(--color-bg); }

.deals-grid {
  display: grid;
  grid-template-columns: 2fr 1fr;
  grid-template-rows: auto auto;
  gap: 1.5rem;
}
.deal-card {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-card);
  display: flex;
  flex-direction: column;
  transition: box-shadow var(--transition);
}
.deal-card:hover { box-shadow: var(--shadow-hover); }

.deal-card.deal-hero { grid-row: 1 / 3; flex-direction: row; align-items: stretch; }
.deal-hero .deal-image-wrap { flex: 1; min-height: 300px; }
.deal-hero .deal-body { flex: 1; }

.deal-image-wrap {
  position: relative;
  overflow: hidden;
  min-height: 200px;
}
.deal-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.4s ease;
}
.deal-card:hover .deal-img { transform: scale(1.05); }

.deal-body {
  padding: 1.75rem;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  justify-content: center;
}
.deal-tag {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  width: fit-content;
  padding: 0.3rem 0.75rem;
  background: var(--color-deal-bg);
  color: var(--color-deal);
  border: 1px solid rgba(224,92,92,.3);
  border-radius: 999px;
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
}
.deal-name {
  font-size: clamp(1.1rem, 2.5vw, 1.5rem);
  font-weight: 700;
  line-height: 1.3;
  color: var(--color-text);
}
.deal-desc { font-size: 0.9rem; color: var(--color-muted); line-height: 1.6; }

.deal-price-row { display: flex; align-items: center; gap: 0.75rem; }
.deal-price { font-size: 1.5rem; font-weight: 800; color: var(--color-accent); }
.deal-original { font-size: 1rem; color: var(--color-muted); text-decoration: line-through; }

/* Countdown */
.countdown {
  display: flex;
  gap: 0.5rem;
  align-items: center;
  flex-wrap: wrap;
}
.countdown-label {
  font-size: 0.78rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--color-muted);
}
.countdown-units { display: flex; gap: 0.4rem; }
.countdown-unit {
  background: var(--color-surface-2);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-sm);
  padding: 0.3rem 0.6rem;
  text-align: center;
  min-width: 2.5rem;
}
.countdown-num {
  font-size: 1rem;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  line-height: 1;
  display: block;
}
.countdown-seg {
  font-size: 0.6rem;
  color: var(--color-muted);
  text-transform: uppercase;
  letter-spacing: 0.05em;
  display: block;
  margin-top: 0.15rem;
}
.countdown-sep { font-size: 1rem; font-weight: 700; color: var(--color-muted); align-self: center; }

.deal-actions { display: flex; gap: 0.75rem; flex-wrap: wrap; }

/* ============================================================
   EDITORIAL
   ============================================================ */
.editorial-section { background: var(--color-surface); }

.editorial-grid {
  display: grid;
  grid-template-columns: 2fr 1fr;
  grid-template-rows: auto;
  gap: 1.5rem;
}

.article-card {
  background: var(--color-surface-2);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  box-shadow: var(--shadow-card);
  transition: transform var(--transition), box-shadow var(--transition);
}
.article-card:hover { transform: translateY(-3px); box-shadow: var(--shadow-hover); }

.article-card.article-featured { grid-column: 1; }
.article-stack {
  grid-column: 2;
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

.article-image-wrap {
  position: relative;
  overflow: hidden;
  aspect-ratio: 16/9;
}
.article-image {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.4s ease;
}
.article-card:hover .article-image { transform: scale(1.04); }

.article-body { padding: 1.5rem; flex: 1; display: flex; flex-direction: column; gap: 0.75rem; }

.article-meta {
  display: flex;
  gap: 1rem;
  align-items: center;
  flex-wrap: wrap;
}
.article-category {
  font-size: 0.72rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--color-accent);
  background: rgba(212,168,83,.1);
  padding: 0.2rem 0.6rem;
  border-radius: 999px;
}
.article-date { font-size: 0.78rem; color: var(--color-muted); }

.article-title {
  font-size: clamp(1rem, 2vw, 1.3rem);
  font-weight: 700;
  color: var(--color-text);
  line-height: 1.35;
}
.article-title a { color: inherit; text-decoration: none; }
.article-title a:hover { color: var(--color-accent-alt); }

.article-excerpt { font-size: 0.9rem; color: var(--color-muted); line-height: 1.65; flex: 1; }

.article-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: 0.75rem;
  border-top: 1px solid var(--color-border);
  margin-top: auto;
}
.article-author {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  font-size: 0.82rem;
  color: var(--color-muted);
}
.author-avatar {
  width: 1.75rem;
  height: 1.75rem;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.7rem;
  font-weight: 700;
  color: #000;
  flex-shrink: 0;
}
.read-time { font-size: 0.78rem; color: var(--color-subtle); }

/* Small article card (in stack) */
.article-card.article-small { flex-direction: row; }
.article-card.article-small .article-image-wrap {
  width: 120px;
  flex-shrink: 0;
  aspect-ratio: 1;
  border-radius: 0;
}
.article-card.article-small .article-body { padding: 1rem; }
.article-card.article-small .article-title { font-size: 0.9rem; }

/* ============================================================
   CATEGORIES STRIP
   ============================================================ */
.categories-section { background: var(--color-bg); padding-block: 3.5rem; }
.categories-scroll {
  display: flex;
  gap: 1rem;
  overflow-x: auto;
  padding-bottom: 0.5rem;
  scroll-snap-type: x mandatory;
  -webkit-overflow-scrolling: touch;
}
.categories-scroll::-webkit-scrollbar { height: 4px; }
.categories-scroll::-webkit-scrollbar-track { background: var(--color-surface); border-radius: 2px; }
.categories-scroll::-webkit-scrollbar-thumb { background: var(--color-border); border-radius: 2px; }

.category-chip {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.6rem;
  flex-shrink: 0;
  scroll-snap-align: start;
  text-decoration: none;
  color: var(--color-muted);
  transition: color var(--transition);
  padding: 0.5rem 0.75rem;
  border-radius: var(--radius-md);
  border: 1px solid transparent;
}
.category-chip:hover,
.category-chip[aria-current="page"] {
  color: var(--color-accent);
  border-color: rgba(212,168,83,.3);
  background: rgba(212,168,83,.05);
}
.category-icon {
  width: 3.5rem;
  height: 3.5rem;
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  background: var(--color-surface-2);
  border: 1px solid var(--color-border);
}
.category-label { font-size: 0.78rem; font-weight: 600; text-align: center; white-space: nowrap; }

/* ============================================================
   FOOTER
   ============================================================ */
.site-footer {
  background: var(--color-surface);
  border-top: 1px solid var(--color-border);
  padding-block: 4rem 2rem;
}
.footer-grid {
  display: grid;
  grid-template-columns: 2fr repeat(3, 1fr);
  gap: 3rem;
  margin-bottom: 3rem;
}
.footer-brand .logo-text { font-size: 1.3rem; }
.footer-desc { font-size: 0.875rem; color: var(--color-muted); margin-top: 0.75rem; line-height: 1.7; max-width: 280px; }
.footer-socials { display: flex; gap: 0.5rem; margin-top: 1.25rem; }
.social-link {
  width: 2.25rem;
  height: 2.25rem;
  border-radius: var(--radius-sm);
  background: var(--color-surface-2);
  border: 1px solid var(--color-border);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-muted);
  text-decoration: none;
  font-size: 0.85rem;
  transition: background var(--transition), color var(--transition);
}
.social-link:hover { background: var(--color-surface-3); color: var(--color-accent); }

.footer-col h3 {
  font-size: 0.8rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--color-text);
  margin-bottom: 1rem;
}
.footer-links { display: flex; flex-direction: column; gap: 0.6rem; }
.footer-links a {
  font-size: 0.875rem;
  color: var(--color-muted);
  text-decoration: none;
  transition: color var(--transition);
}
.footer-links a:hover { color: var(--color-accent); }

.footer-bottom {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 1rem;
  padding-top: 2rem;
  border-top: 1px solid var(--color-border);
}
.copyright { font-size: 0.8rem; color: var(--color-muted); }
.payment-icons { display: flex; gap: 0.5rem; align-items: center; }
.payment-chip {
  padding: 0.25rem 0.6rem;
  background: var(--color-surface-2);
  border: 1px solid var(--color-border);
  border-radius: 4px;
  font-size: 0.7rem;
  font-weight: 700;
  color: var(--color-muted);
  letter-spacing: 0.04em;
}

/* ============================================================
   TOAST / status messages
   ============================================================ */
.toast-region {
  position: fixed;
  bottom: 1.5rem;
  right: 1.5rem;
  z-index: 500;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  pointer-events: none;
}
.toast {
  background: var(--color-surface-2);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  padding: 0.9rem 1.25rem;
  min-width: 240px;
  max-width: 360px;
  display: flex;
  gap: 0.75rem;
  align-items: flex-start;
  box-shadow: var(--shadow-hover);
  pointer-events: all;
  animation: toast-in 0.25s ease forwards;
}
.toast-icon { font-size: 1.1rem; flex-shrink: 0; }
.toast-msg { font-size: 0.875rem; color: var(--color-text); line-height: 1.5; }
.toast-title { font-weight: 700; margin-bottom: 0.15rem; }
.toast.toast-exit { animation: toast-out 0.2s ease forwards; }

@keyframes toast-in {
  from { opacity: 0; transform: translateY(12px); }
  to   { opacity: 1; transform: translateY(0); }
}
@keyframes toast-out {
  from { opacity: 1; transform: translateY(0); }
  to   { opacity: 0; transform: translateY(12px); }
}

/* ============================================================
   Forced Colors
   ============================================================ */
@media (forced-colors: active) {
  .btn { border: 2px solid ButtonBorder; }
  .product-card,
  .deal-card,
  .article-card { border: 1px solid ButtonBorder; }
  .site-header { border-bottom: 1px solid ButtonBorder; }
  :focus-visible { outline: 3px solid Highlight; }
}

/* ============================================================
   Reduced Motion
   ============================================================ */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.001ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.001ms !important;
    scroll-behavior: auto !important;
  }
}

/* ============================================================
   RESPONSIVE
   ============================================================ */

/* ≤ 1024px — tablet */
@media (max-width: 1024px) {
  .deals-grid { grid-template-columns: 1fr; }
  .deal-card.deal-hero { flex-direction: column; }
  .deal-hero .deal-image-wrap { min-height: 260px; flex: none; }
  .editorial-grid { grid-template-columns: 1fr; }
  .article-stack { flex-direction: row; }
  .footer-grid { grid-template-columns: 1fr 1fr; }
}

/* ≤ 768px — mobile */
@media (max-width: 768px) {
  section { padding-block: 3.5rem; }
  .primary-nav { display: none; }
  .primary-nav.nav-open { display: block; }
  .menu-toggle { display: flex; }
  .primary-nav.nav-open .nav-list {
    flex-direction: column;
    position: absolute;
    top: 100%;
    left: 0;
    right: 0;
    background: var(--color-surface);
    border-bottom: 1px solid var(--color-border);
    padding: 1rem;
    gap: 0.25rem;
  }
  .primary-nav.nav-open .nav-link { display: block; padding: 0.75rem 1rem; }
  .header-inner { flex-wrap: wrap; position: relative; }
  .hero-stats { gap: 1.5rem; flex-wrap: wrap; }
  .article-stack { flex-direction: column; }
  .article-card.article-small { flex-direction: column; }
  .article-card.article-small .article-image-wrap { width: 100%; aspect-ratio: 16/9; }
  .footer-grid { grid-template-columns: 1fr; gap: 2rem; }
  .footer-bottom { flex-direction: column; align-items: flex-start; }
}

/* ≤ 480px — small mobile */
@media (max-width: 480px) {
  .hero-title { font-size: 2rem; }
  .product-grid { grid-template-columns: repeat(auto-fill, minmax(200px, 1fr)); }
  .deals-grid { grid-template-columns: 1fr; }
  .deal-hero .deal-image-wrap { min-height: 200px; }
}

/* ≤ 320px — reflow target */
@media (max-width: 320px) {
  .container { padding-inline: 1rem; }
  .hero-actions { flex-direction: column; align-items: stretch; }
  .btn { justify-content: center; }
  .deal-actions { flex-direction: column; }
  .countdown-units { gap: 0.2rem; }
  .countdown-unit { min-width: 2rem; padding: 0.25rem 0.4rem; }
}

