+/* ============================================================
+   Design tokens
+   ============================================================ */
+:root {
+  --color-bg:         #0b0b10;
+  --color-surface:    #13131e;
+  --color-surface-2:  #1b1b2a;
+  --color-surface-3:  #22223a;
+  --color-text:       #eeeef5;
+  --color-muted:      #8888a2;
+  --color-subtle:     #55556a;
+  --color-accent:     #d4a853;
+  --color-accent-alt: #e8be6e;
+  --color-deal:       #e05c5c;
+  --color-deal-bg:    #2a1010;
+  --color-border:     #2a2a40;
+  --color-focus:      #6b9cff;
+  --color-link:       #a8c4ff;
+  --radius-sm:        6px;
+  --radius-md:        12px;
+  --radius-lg:        18px;
+  --shadow-card:      0 2px 16px rgba(0,0,0,.55);
+  --shadow-hover:     0 8px 32px rgba(0,0,0,.7);
+  --transition:       0.2s ease;
+  --font-sans:        'Segoe UI', system-ui, -apple-system, sans-serif;
+}
+
+/* ============================================================
+   Reset & base
+   ============================================================ */
+*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
+
+html { scroll-behavior: smooth; }
+
+body {
+  background-color: var(--color-bg);
+  color: var(--color-text);
+  font-family: var(--font-sans);
+  font-size: 1rem;
+  line-height: 1.6;
+  -webkit-font-smoothing: antialiased;
+}
+
+img { display: block; max-width: 100%; height: auto; }
+a { color: var(--color-link); text-decoration: underline; }
+a:hover { color: var(--color-accent-alt); }
+ul, ol { list-style: none; }
+
+/* ============================================================
+   Skip link
+   ============================================================ */
+.skip-link {
+  position: absolute;
+  top: 0;
+  left: 0;
+  padding: 0.75rem 1.25rem;
+  background: var(--color-accent);
+  color: #000;
+  font-weight: 700;
+  border-radius: 0 0 var(--radius-sm) 0;
+  z-index: 1000;
+  text-decoration: none;
+}
+.skip-link:not(:focus):not(:active) {
+  clip: rect(0 0 0 0);
+  clip-path: inset(50%);
+  height: 1px;
+  overflow: hidden;
+  position: absolute;
+  white-space: nowrap;
+  width: 1px;
+}
+.skip-link:focus { outline: 3px solid #000; outline-offset: 2px; }
+
+/* ============================================================
+   Focus styles (global)
+   ============================================================ */
+:focus-visible {
+  outline: 3px solid var(--color-focus);
+  outline-offset: 3px;
+}
+/* paired transparent outline for forced-colors */
+:focus-visible {
+  box-shadow: 0 0 0 3px var(--color-focus);
+  outline: 2px solid transparent;
+}
+
+/* ============================================================
+   Screen-reader only utility
+   ============================================================ */
+.sr-only {
+  clip: rect(0 0 0 0);
+  clip-path: inset(50%);
+  height: 1px;
+  overflow: hidden;
+  position: absolute;
+  white-space: nowrap;
+  width: 1px;
+}
+
+/* ============================================================
+   Layout utilities
+   ============================================================ */
+.container {
+  width: min(100%, 1280px);
+  margin-inline: auto;
+  padding-inline: 1.5rem;
+}
+
+section { padding-block: 5rem; }
+
+.section-header {
+  display: flex;
+  align-items: baseline;
+  justify-content: space-between;
+  gap: 1rem;
+  flex-wrap: wrap;
+  margin-bottom: 2.5rem;
+}
+.section-title {
+  font-size: clamp(1.5rem, 3vw, 2rem);
+  font-weight: 700;
+  letter-spacing: -0.02em;
+  color: var(--color-text);
+}
+.section-link {
+  font-size: 0.9rem;
+  font-weight: 600;
+  color: var(--color-accent);
+  text-decoration: none;
+  white-space: nowrap;
+}
+.section-link:hover { color: var(--color-accent-alt); text-decoration: underline; }
+
+/* ============================================================
+   Buttons
+   ============================================================ */
+.btn {
+  display: inline-flex;
+  align-items: center;
+  gap: 0.5rem;
+  padding: 0.7rem 1.5rem;
+  border-radius: var(--radius-sm);
+  font-family: inherit;
+  font-size: 0.95rem;
+  font-weight: 600;
+  cursor: pointer;
+  text-decoration: none;
+  transition: background var(--transition), color var(--transition), transform var(--transition);
+  border: 2px solid transparent;
+}
+.btn:focus-visible {
+  outline: 2px solid transparent;
+  box-shadow: 0 0 0 3px var(--color-focus);
+}
+.btn-primary {
+  background: var(--color-accent);
+  color: #0b0b10;
+}
+.btn-primary:hover {
+  background: var(--color-accent-alt);
+  color: #0b0b10;
+  transform: translateY(-1px);
+}
+.btn-outline {
+  background: transparent;
+  color: var(--color-accent);
+  border-color: var(--color-accent);
+}
+.btn-outline:hover {
+  background: var(--color-accent);
+  color: #0b0b10;
+}
+.btn-ghost {
+  background: var(--color-surface-2);
+  color: var(--color-text);
+  border-color: var(--color-border);
+}
+.btn-ghost:hover { background: var(--color-surface-3); }
+
+.btn-icon {
+  background: none;
+  border: none;
+  cursor: pointer;
+  display: inline-flex;
+  align-items: center;
+  justify-content: center;
+  padding: 0.5rem;
+  border-radius: var(--radius-sm);
+  color: var(--color-text);
+  transition: background var(--transition);
+}
+.btn-icon:hover { background: var(--color-surface-2); }
+.btn-icon:focus-visible {
+  outline: 2px solid transparent;
+  box-shadow: 0 0 0 3px var(--color-focus);
+}
+
+/* ============================================================
+   Divider
+   ============================================================ */
+.divider {
+  border: none;
+  border-top: 1px solid var(--color-border);
+}
+
+/* ============================================================
+   HEADER
+   ============================================================ */
+.site-header {
+  position: sticky;
+  top: 0;
+  z-index: 100;
+  background: rgba(11, 11, 16, 0.9);
+  backdrop-filter: blur(12px);
+  -webkit-backdrop-filter: blur(12px);
+  border-bottom: 1px solid var(--color-border);
+}
+.header-inner {
+  display: flex;
+  align-items: center;
+  gap: 2rem;
+  height: 4rem;
+}
+.site-logo {
+  display: flex;
+  align-items: center;
+  gap: 0.6rem;
+  text-decoration: none;
+  flex-shrink: 0;
+}
+.logo-mark {
+  width: 36px;
+  height: 36px;
+  background: var(--color-accent);
+  border-radius: var(--radius-sm);
+  display: flex;
+  align-items: center;
+  justify-content: center;
+  font-size: 1.1rem;
+}
+.logo-text {
+  font-size: 1.2rem;
+  font-weight: 800;
+  letter-spacing: -0.03em;
+  color: var(--color-text);
+}
+.logo-text span { color: var(--color-accent); }
+
+/* Primary nav */
+.primary-nav { margin-inline-start: auto; }
+.nav-list {
+  display: flex;
+  gap: 0.25rem;
+}
+.nav-link {
+  display: inline-block;
+  padding: 0.5rem 0.75rem;
+  border-radius: var(--radius-sm);
+  font-size: 0.9rem;
+  font-weight: 500;
+  color: var(--color-muted);
+  text-decoration: none;
+  transition: color var(--transition), background var(--transition);
+}
+.nav-link:hover,
+.nav-link[aria-current="page"] {
+  color: var(--color-text);
+  background: var(--color-surface-2);
+}
+.nav-link[aria-current="page"] { color: var(--color-accent); }
+
+/* Header actions */
+.header-actions {
+  display: flex;
+  align-items: center;
+  gap: 0.25rem;
+  margin-inline-start: auto;
+}
+.cart-count {
+  display: inline-flex;
+  align-items: center;
+  justify-content: center;
+  min-width: 1.25rem;
+  height: 1.25rem;
+  padding: 0 0.25rem;
+  background: var(--color-accent);
+  color: #0b0b10;
+  font-size: 0.7rem;
+  font-weight: 700;
+  border-radius: 999px;
+  margin-inline-start: -0.5rem;
+  margin-block-end: 1rem;
+}
+
+/* Mobile menu toggle */
