/* ============================================================
   Cart state
   ============================================================ */
const cart = { items: [], total: 0 };

function getCartCount() { return cart.items.reduce((s, i) => s + i.qty, 0); }

function updateCartUI() {
  const countEl = document.getElementById('cart-count');
  const countAnnounce = document.getElementById('cart-announce');
  const n = getCartCount();
  if (countEl) {
    countEl.textContent = n;
    countEl.hidden = n === 0;
  }
  if (countAnnounce) {
    countAnnounce.textContent = n === 0
      ? 'Cart is empty.'
      : `${n} item${n !== 1 ? 's' : ''} in cart.`;
  }
}

function addToCart(name, price) {
  const existing = cart.items.find(i => i.name === name);
  if (existing) {
    existing.qty += 1;
  } else {
    cart.items.push({ name, price, qty: 1 });
  }
  cart.total += price;
  updateCartUI();
  showToast('Added to cart', `${name} has been added to your cart.`, '🛒');
}

/* ============================================================
