   ============================================================ */
function showToast(title, message, icon = 'ℹ️') {
  const region = document.getElementById('toast-region');
  if (!region) return;

  const toast = document.createElement('div');
  toast.className = 'toast';
  toast.setAttribute('role', 'status');
  toast.innerHTML = `
    <span class="toast-icon" aria-hidden="true">${icon}</span>
    <div class="toast-msg">
      <div class="toast-title">${escHtml(title)}</div>
      <div>${escHtml(message)}</div>
    </div>`;

  region.appendChild(toast);

  const DURATION = 4000;
  const ANIM = 220;
  setTimeout(() => {
    toast.classList.add('toast-exit');
    setTimeout(() => toast.remove(), ANIM);
  }, DURATION);
}

function escHtml(str) {
  return String(str)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

/* ============================================================
   Wishlist toggle
   ============================================================ */
function initWishlistButtons() {
  document.querySelectorAll('.product-wishlist').forEach(btn => {
    btn.addEventListener('click', () => {
      const pressed = btn.getAttribute('aria-pressed') === 'true';
      btn.setAttribute('aria-pressed', String(!pressed));
      const productName = btn.dataset.product || 'item';
      if (!pressed) {
        showToast('Wishlist', `${productName} added to your wishlist.`, '♥');
      }
    });
  });
}

/* ============================================================
   Add-to-cart buttons
   ============================================================ */
function initCartButtons() {
  document.querySelectorAll('[data-add-to-cart]').forEach(btn => {
    btn.addEventListener('click', () => {
      const name  = btn.dataset.addToCart;
      const price = parseFloat(btn.dataset.price) || 0;
      addToCart(name, price);
    });
  });
}

/* ============================================================
   Countdown timers
   ============================================================ */
function initCountdowns() {
  document.querySelectorAll('[data-countdown]').forEach(el => {
    const endMs = Date.now() + parseInt(el.dataset.countdown, 10) * 1000;

    function tick() {
      const diff = Math.max(0, endMs - Date.now());
      const h = Math.floor(diff / 3_600_000);
      const m = Math.floor((diff % 3_600_000) / 60_000);
      const s = Math.floor((diff % 60_000) / 1000);

      const hEl = el.querySelector('[data-unit="h"]');
      const mEl = el.querySelector('[data-unit="m"]');
      const sEl = el.querySelector('[data-unit="s"]');
      if (hEl) hEl.textContent = String(h).padStart(2, '0');
      if (mEl) mEl.textContent = String(m).padStart(2, '0');
      if (sEl) sEl.textContent = String(s).padStart(2, '0');

      // Update accessible live region summary
      const live = el.querySelector('[data-countdown-live]');
      if (live) {
        live.textContent = `${h} hours, ${m} minutes, ${s} seconds remaining.`;
      }

      if (diff > 0) requestAnimationFrame(tick);
    }
    tick();
  });
}

/* ============================================================
   Mobile nav toggle
   ============================================================ */
function initMobileNav() {
  const toggle = document.getElementById('menu-toggle');
  const nav    = document.getElementById('primary-nav');
  if (!toggle || !nav) return;

  toggle.addEventListener('click', () => {
    const open = toggle.getAttribute('aria-expanded') === 'true';
    toggle.setAttribute('aria-expanded', String(!open));
    nav.classList.toggle('nav-open', !open);
  });

  // Close on Escape
  document.addEventListener('keydown', e => {
    if (e.key === 'Escape' && toggle.getAttribute('aria-expanded') === 'true') {
      toggle.setAttribute('aria-expanded', 'false');
      nav.classList.remove('nav-open');
      toggle.focus();
    }
  });

  // Close when clicking outside
  document.addEventListener('click', e => {
    if (!nav.contains(e.target) && !toggle.contains(e.target)) {
      toggle.setAttribute('aria-expanded', 'false');
      nav.classList.remove('nav-open');
    }
  });
}

/* ============================================================
   Smooth-scroll skip link
   ============================================================ */
function initSkipLink() {
  const skip = document.querySelector('.skip-link');
  const main = document.getElementById('main-content');
  if (!skip || !main) return;
  skip.addEventListener('click', e => {
    e.preventDefault();
    main.focus();
    main.scrollIntoView({ behavior: 'smooth' });
  });
}

/* ============================================================
   Init
