}

/* ============================================================
   FEATURED PRODUCTS
   ============================================================ */
.featured-products { background: var(--color-surface); }

.product-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
  gap: 1.5rem;
}

.product-card {
  background: var(--color-surface-2);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  box-shadow: var(--shadow-card);
  transition: transform var(--transition), box-shadow var(--transition);
  position: relative;
}
.product-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-hover);
}

.product-image-wrap {
  position: relative;
  aspect-ratio: 4/3;
  overflow: hidden;
}
.product-image {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.4s ease;
}
.product-card:hover .product-image { transform: scale(1.05); }

.product-badge {
  position: absolute;
  top: 0.75rem;
  left: 0.75rem;
  padding: 0.25rem 0.6rem;
  border-radius: 999px;
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}
.badge-new { background: var(--color-accent); color: #000; }
.badge-sale { background: var(--color-deal); color: #fff; }
.badge-hot { background: #9b59b6; color: #fff; }

.product-wishlist {
  position: absolute;
  top: 0.75rem;
  right: 0.75rem;
  background: rgba(19,19,30,.8);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-sm);
  width: 2rem;
  height: 2rem;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: background var(--transition);
  color: var(--color-muted);
}
.product-wishlist:hover { background: var(--color-surface-3); color: var(--color-deal); }
.product-wishlist:focus-visible {
  outline: 2px solid transparent;
  box-shadow: 0 0 0 3px var(--color-focus);
}
.product-wishlist[aria-pressed="true"] { color: var(--color-deal); }

.product-body {
  padding: 1.25rem;
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}
.product-category {
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--color-muted);
}
.product-name {
  font-size: 1rem;
  font-weight: 600;
  color: var(--color-text);
  line-height: 1.4;
}
.product-rating {
  display: flex;
  align-items: center;
  gap: 0.4rem;
}
.stars { color: var(--color-accent); font-size: 0.8rem; line-height: 1; }
.rating-count { font-size: 0.78rem; color: var(--color-muted); }

.product-price-row {
  display: flex;
