  gap: 0.75rem;
  flex-wrap: wrap;
  margin-top: auto;
}
.price-current {
  font-size: 1.2rem;
  font-weight: 700;
  color: var(--color-accent);
}
.price-original {
  font-size: 0.9rem;
  color: var(--color-muted);
  text-decoration: line-through;
}
.price-save {
  font-size: 0.75rem;
  font-weight: 700;
  color: var(--color-deal);
  background: var(--color-deal-bg);
  padding: 0.15rem 0.45rem;
  border-radius: 999px;
}

.product-footer {
  padding: 1rem 1.25rem;
  border-top: 1px solid var(--color-border);
}
.add-to-cart {
  width: 100%;
  justify-content: center;
}

/* ============================================================
   DEALS SECTION
   ============================================================ */
.deals-section { background: var(--color-bg); }

.deals-grid {
  display: grid;
  grid-template-columns: 2fr 1fr;
  grid-template-rows: auto auto;
  gap: 1.5rem;
  list-style: none;
  padding: 0;
}
.deal-card {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-card);
  display: flex;
  flex-direction: column;
  transition: box-shadow var(--transition);
}
.deal-card:hover { box-shadow: var(--shadow-hover); }

.deal-card.deal-hero { grid-row: 1 / 3; flex-direction: row; align-items: stretch; }
.deal-hero .deal-image-wrap { flex: 1; min-height: 300px; }
.deal-hero .deal-body { flex: 1; }

.deal-image-wrap {
  position: relative;
  overflow: hidden;
  min-height: 200px;
}
.deal-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.4s ease;
}
.deal-card:hover .deal-img { transform: scale(1.05); }

.deal-body {
  padding: 1.75rem;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  justify-content: center;
}
.deal-tag {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  width: fit-content;
  padding: 0.3rem 0.75rem;
  background: var(--color-deal-bg);
  color: var(--color-deal);
  border: 1px solid rgba(224,92,92,.3);
  border-radius: 999px;
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
}
.deal-name {
  font-size: clamp(1.1rem, 2.5vw, 1.5rem);
  font-weight: 700;
  line-height: 1.3;
  color: var(--color-text);
}
.deal-desc { font-size: 0.9rem; color: var(--color-muted); line-height: 1.6; }

.deal-price-row { display: flex; align-items: center; gap: 0.75rem; }
.deal-price { font-size: 1.5rem; font-weight: 800; color: var(--color-accent); }
.deal-original { font-size: 1rem; color: var(--color-muted); text-decoration: line-through; }

/* Countdown */
.countdown {
  display: flex;
  gap: 0.5rem;
  align-items: center;
  flex-wrap: wrap;
}
.countdown-label {
  font-size: 0.78rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--color-muted);
}
.countdown-units { display: flex; gap: 0.4rem; }
.countdown-unit {
  background: var(--color-surface-2);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-sm);
  padding: 0.3rem 0.6rem;
  text-align: center;
  min-width: 2.5rem;
}
.countdown-num {
  font-size: 1rem;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  line-height: 1;
  display: block;
}
.countdown-seg {
  font-size: 0.6rem;
  color: var(--color-muted);
  text-transform: uppercase;
  letter-spacing: 0.05em;
  display: block;
  margin-top: 0.15rem;
}
.countdown-sep { font-size: 1rem; font-weight: 700; color: var(--color-muted); align-self: center; }

.deal-actions { display: flex; gap: 0.75rem; flex-wrap: wrap; }

/* ============================================================
   EDITORIAL
   ============================================================ */
.editorial-section { background: var(--color-surface); }

.editorial-grid {
  display: grid;
  grid-template-columns: 2fr 1fr;
  grid-template-rows: auto;
  gap: 1.5rem;
}

.article-card {
  background: var(--color-surface-2);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  box-shadow: var(--shadow-card);
  transition: transform var(--transition), box-shadow var(--transition);
}
.article-card:hover { transform: translateY(-3px); box-shadow: var(--shadow-hover); }

.article-card.article-featured { grid-column: 1; }
.article-stack {
  grid-column: 2;
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
  list-style: none;
  padding: 0;
}

.article-image-wrap {
  position: relative;
  overflow: hidden;
  aspect-ratio: 16/9;
}
.article-image {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.4s ease;
}
.article-card:hover .article-image { transform: scale(1.04); }

.article-body { padding: 1.5rem; flex: 1; display: flex; flex-direction: column; gap: 0.75rem; }

.article-meta {
  display: flex;
  gap: 1rem;
  align-items: center;
  flex-wrap: wrap;
}
.article-category {
  font-size: 0.72rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--color-accent);
  background: rgba(212,168,83,.1);
  padding: 0.2rem 0.6rem;
  border-radius: 999px;
}
.article-date { font-size: 0.78rem; color: var(--color-muted); }

.article-title {
  font-size: clamp(1rem, 2vw, 1.3rem);
  font-weight: 700;
  color: var(--color-text);
  line-height: 1.35;
}
.article-title a { color: inherit; text-decoration: none; }
.article-title a:hover { color: var(--color-accent-alt); }

.article-excerpt { font-size: 0.9rem; color: var(--color-muted); line-height: 1.65; flex: 1; }

.article-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: 0.75rem;
  border-top: 1px solid var(--color-border);
  margin-top: auto;
}
.article-author {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  font-size: 0.82rem;
  color: var(--color-muted);
}
.author-avatar {
  width: 1.75rem;
  height: 1.75rem;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.7rem;
  font-weight: 700;
  color: #000;
  flex-shrink: 0;
}
.read-time { font-size: 0.78rem; color: var(--color-subtle); }

/* Small article card (in stack) */
.article-card.article-small { flex-direction: row; }
.article-card.article-small .article-image-wrap {
  width: 120px;
  flex-shrink: 0;
  aspect-ratio: 1;
  border-radius: 0;
}
.article-card.article-small .article-body { padding: 1rem; }
.article-card.article-small .article-title { font-size: 0.9rem; }

/* ============================================================
   CATEGORIES STRIP
   ============================================================ */
.categories-section { background: var(--color-bg); padding-block: 3.5rem; }
.categories-scroll {
  display: flex;
  gap: 1rem;
  overflow-x: auto;
  padding-bottom: 0.5rem;
  scroll-snap-type: x mandatory;
  -webkit-overflow-scrolling: touch;
}
.categories-scroll::-webkit-scrollbar { height: 4px; }
.categories-scroll::-webkit-scrollbar-track { background: var(--color-surface); border-radius: 2px; }
.categories-scroll::-webkit-scrollbar-thumb { background: var(--color-border); border-radius: 2px; }

.category-chip {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.6rem;
  flex-shrink: 0;
  scroll-snap-align: start;
  text-decoration: none;
  color: var(--color-muted);
  transition: color var(--transition);
  padding: 0.5rem 0.75rem;
  border-radius: var(--radius-md);
  border: 1px solid transparent;
}
.category-chip:hover,
.category-chip[aria-current="page"] {
  color: var(--color-accent);
  border-color: rgba(212,168,83,.3);
  background: rgba(212,168,83,.05);
}
.category-icon {
  width: 3.5rem;
  height: 3.5rem;
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  background: var(--color-surface-2);
  border: 1px solid var(--color-border);
}
.category-label { font-size: 0.78rem; font-weight: 600; text-align: center; white-space: nowrap; }

/* li wrappers inside CSS grid/flex lists must not create extra boxes */
.deals-grid > li,
.article-stack > li {
  display: contents;
}
.site-footer {
  background: var(--color-surface);
  border-top: 1px solid var(--color-border);
  padding-block: 4rem 2rem;
}
.footer-grid {
  display: grid;
  grid-template-columns: 2fr repeat(3, 1fr);
  gap: 3rem;
  margin-bottom: 3rem;
}
.footer-brand .logo-text { font-size: 1.3rem; }
.footer-desc { font-size: 0.875rem; color: var(--color-muted); margin-top: 0.75rem; line-height: 1.7; max-width: 280px; }
.footer-socials { display: flex; gap: 0.5rem; margin-top: 1.25rem; }
.social-link {
  width: 2.25rem;
  height: 2.25rem;
  border-radius: var(--radius-sm);
  background: var(--color-surface-2);
  border: 1px solid var(--color-border);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-muted);
  text-decoration: none;
  font-size: 0.85rem;
  transition: background var(--transition), color var(--transition);
}
.social-link:hover { background: var(--color-surface-3); color: var(--color-accent); }

.footer-col h3 {
  font-size: 0.8rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--color-text);
  margin-bottom: 1rem;
}
.footer-links { display: flex; flex-direction: column; gap: 0.6rem; }
.footer-links a {
  font-size: 0.875rem;
  color: var(--color-muted);
  text-decoration: none;
  transition: color var(--transition);
}
.footer-links a:hover { color: var(--color-accent); }

.footer-bottom {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 1rem;
  padding-top: 2rem;
  border-top: 1px solid var(--color-border);
}
.copyright { font-size: 0.8rem; color: var(--color-muted); }
.payment-icons { display: flex; gap: 0.5rem; align-items: center; }
.payment-chip {
  padding: 0.25rem 0.6rem;
  background: var(--color-surface-2);
  border: 1px solid var(--color-border);
  border-radius: 4px;
  font-size: 0.7rem;
  font-weight: 700;
  color: var(--color-muted);
  letter-spacing: 0.04em;
}

/* ============================================================
   TOAST / status messages
   ============================================================ */
.toast-region {
  position: fixed;
  bottom: 1.5rem;
  right: 1.5rem;
  z-index: 500;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  pointer-events: none;
}
.toast {
  background: var(--color-surface-2);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  padding: 0.9rem 1.25rem;
  min-width: 240px;
  max-width: 360px;
  display: flex;
  gap: 0.75rem;
  align-items: flex-start;
  box-shadow: var(--shadow-hover);
  pointer-events: all;
  animation: toast-in 0.25s ease forwards;
}
.toast-icon { font-size: 1.1rem; flex-shrink: 0; }
.toast-msg { font-size: 0.875rem; color: var(--color-text); line-height: 1.5; }
.toast-title { font-weight: 700; margin-bottom: 0.15rem; }
.toast.toast-exit { animation: toast-out 0.2s ease forwards; }

@keyframes toast-in {
  from { opacity: 0; transform: translateY(12px); }
  to   { opacity: 1; transform: translateY(0); }
}
@keyframes toast-out {
  from { opacity: 1; transform: translateY(0); }
  to   { opacity: 0; transform: translateY(12px); }
}

/* ============================================================
   Forced Colors
   ============================================================ */
@media (forced-colors: active) {
  .btn { border: 2px solid ButtonBorder; }
  .product-card,
  .deal-card,
  .article-card { border: 1px solid ButtonBorder; }
  .site-header { border-bottom: 1px solid ButtonBorder; }
  :focus-visible { outline: 3px solid Highlight; }
